import os, re

d = os.environ.get('RLM_SESSION_DIR')
if d:
    sessions_file = os.path.join(d, '../../sessions/' + os.path.basename(d) + '.jsonl')
    if os.path.exists(sessions_file):
        t = open(sessions_file).read()
        G = {}
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
            k, h, w = m[1], int(m[2]), int(m[3])
            rows = [r.split() for r in t[m.end():].split('\n')[:h]]
            if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
                G[k] = [[int(x) for x in r] for r in rows]
        print("Loaded:", sorted(G.keys()))
    else:
        print("No sessions file found at:", sessions_file)
else:
    print("RLM_SESSION_DIR not set")

# Analyze the demo pair to understand the rule

import os, json

d = os.environ.get('RLM_SESSION_DIR')
if d:
    sessions_file = os.path.join(d, '../../sessions/' + os.path.basename(d) + '.jsonl')
    if os.path.exists(sessions_file):
        t = open(sessions_file).read()
        G = {}
        for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
            k, h, w = m[1], int(m[2]), int(m[3])
            rows = [r.split() for r in t[m.end():].split('\n')[:h]]
            if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
                G[k] = [[int(x) for x in r] for r in rows]
        print("Loaded:", sorted(G.keys()))

        # Helper to count neighbors with value v
        def count_neighbors(grid, i, j, v):
            h, w = len(grid), len(grid[0])
            count = 0
            for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                ni, nj = i+di, j+dj
                if 0 <= ni < h and 0 <= nj < w and grid[ni][nj] == v:
                    count += 1
            return count

        # Check demo input - find cells that change from 8 to 4
        print("\n=== Demo Pair 1 Analysis ===")
        inp = G['Demo pair 1']
        outp = G['Demo pair 1_out']

        for i in range(len(inp)):
            for j in range(len(inp[0])):
                if inp[i][j] != outp[i][j]:
                    print(f"Changed at ({i},{j}): {inp[i][j]} -> {outp[i][j]}")
                    print(f"  Neighbors count: {count_neighbors(inp, i, j, inp[i][j])}")

        # Check if any cell in input has >=4 neighbors with same value
        print("\n=== Cells with >=4 same-valued neighbors in demo input ===")
        for i in range(len(inp)):
            for j in range(len(inp[0])):
                if count_neighbors(inp, i, j, inp[i][j]) >= 4:
                    print(f"Cell ({i},{j})={inp[i][j]} has {count_neighbors(inp, i, j, inp[i][j])} neighbors")
